From 15acfc63a22690ef8161b3ba21b408c835ac9075 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:00:42 +0100
Subject: [PATCH] Applet: offer keyboard shortcut config when configure is
 overridden
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Notifications, Bluetooth and others make Configure open System Settings,
so as standalone widgets their activation shortcut couldn't be set. Add
a Configure Keyboard Shortcut… entry opening the standard config dialog.

BUG: 503440
---
 src/plasma/private/applet_p.cpp              | 17 +++++++++++++++++
 src/plasmaquick/plasmoid/containmentitem.cpp |  4 ++++
 2 files changed, 21 insertions(+)

diff --git a/src/plasma/private/applet_p.cpp b/src/plasma/private/applet_p.cpp
index 37297d115..440b5a4ab 100644
--- a/src/plasma/private/applet_p.cpp
+++ b/src/plasma/private/applet_p.cpp
@@ -20,6 +20,7 @@
 #include <QStandardPaths>
 #include <QTimer>

+#include <KAuthorized>
 #include <KConfigLoader>
 #include <KGlobalAccel>
 #include <KLocalizedString>
@@ -148,6 +149,22 @@ void AppletPrivate::init(const QVariantList &args)
             }
             a->setVisible(hasAlternatives);
         });
+
+        QAction *shortcutAction = new QAction(QIcon::fromTheme(QStringLiteral("configure-shortcuts")), i18n("Configure Keyboard Shortcut…"), q);
+        shortcutAction->setVisible(false);
+        q->setInternalAction(QStringLiteral("configureShortcut"), shortcutAction);
+        QObject::connect(shortcutAction, &QAction::triggered, q, [this] {
+            requestConfiguration();
+        });
+
+        QPointer<QAction> defaultConfigAction = actions.value(QStringLiteral("configure"));
+        QObject::connect(q, &Applet::contextualActionsAboutToShow, shortcutAction, [this, shortcutAction, defaultConfigAction]() {
+            QAction *configAction = actions.value(QStringLiteral("configure"));
+            const bool unlocked = q->immutability() == Types::Mutable;
+            const bool canConfig = hasConfigurationInterface && (unlocked || KAuthorized::authorize(QStringLiteral("plasma/allow_configure_when_locked")));
+            // Applets that replace the configure action can't otherwise reach their keyboard shortcut page
+            shortcutAction->setVisible(configAction && configAction != defaultConfigAction && canConfig);
+        });
     }
 }

diff --git a/src/plasmaquick/plasmoid/containmentitem.cpp b/src/plasmaquick/plasmoid/containmentitem.cpp
index d8f65fc21..6617da413 100644
--- a/src/plasmaquick/plasmoid/containmentitem.cpp
+++ b/src/plasmaquick/plasmoid/containmentitem.cpp
@@ -967,6 +967,10 @@ void ContainmentItem::addAppletActions(QMenu *desktopMenu, Plasma::Applet *apple
         if (configureApplet && configureApplet->isEnabled()) {
             desktopMenu->addAction(configureApplet);
         }
+        QAction *configureShortcut = applet->internalAction(QStringLiteral("configureShortcut"));
+        if (configureShortcut && configureShortcut->isVisible()) {
+            desktopMenu->addAction(configureShortcut);
+        }
         QAction *appletAlternatives = applet->internalAction(QStringLiteral("alternatives"));
         if (appletAlternatives && appletAlternatives->isEnabled()) {
             desktopMenu->addAction(appletAlternatives);
-- 
